// ============================================================================
// Referencia de Hilti: número de vueltas REALES de cinta CP 648-E según
// diámetro (no un cálculo derivado — tabla que Kevin sacó directo de Hilti).
// El código "2x4"/"3x6" significa instalación en varios tramos de cinta (ej.
// 2 tiras de 4 vueltas cada una), no una sola tira continua — se muestra tal
// cual, no se puede reducir a un solo número.
// ============================================================================
const VUELTAS_CINTA_NO_AISLADA = {
  entrepiso_concreto: [[2.5, 1], [3, 1], [4, 2], [6, 3], [8, 4], [10, "2x4"], [12, "2x4"]],
  pared_concreto: [[2.5, 1], [3, 1], [4, 2], [6, 3], [8, 4], [10, "2x4"], [12, "2x4"]],
  pared_gypsum: [[2.5, 2], [3, 2], [4, 2], [6, 3], [8, 4], [10, "2x4"], [12, "2x4"]],
};
const VUELTAS_CINTA_AISLADA_DIAM_TOTAL = [[2, 1], [3, 1], [4, 3], [6, 3], [8, 4], [10, "2x4"], [12, "2x4"], [14, "3x6"]];

function buscarVueltasEnTabla(tabla, diamIn) {
  const ordenada = tabla.slice().sort((a, b) => a[0] - b[0]);
  for (const [d, v] of ordenada) {
    if (diamIn <= d + 1e-9) return v;
  }
  return null; // diámetro más grande que cualquier bucket de la referencia
}

// Vueltas de cinta CP 648-E para una fila de Penetrantes (null si no aplica).
function vueltasCintaPenetrante(row) {
  const L = row.L, M = row.M, N = row.N, P = row.P;
  if (neq(P, MAT_CINTA_CON) && neq(P, MAT_CINTA_SIN)) return null;
  if (eq(L, TIPO_TUB_COBRE_HVAC)) {
    if (row.E === "" || row.E === null || row.E === undefined) return 2; // sin dato de aislamiento
    return (n(row.D) <= 7 / 8 && n(row.E) <= 1 / 2) ? 1 : 2;
  }
  if (eq(L, TIPO_TUB_COMB_AISL)) {
    return buscarVueltasEnTabla(VUELTAS_CINTA_AISLADA_DIAM_TOTAL, n(row.D) + 2 * n(row.E));
  }
  if (eq(L, TIPO_TUB_COMB)) {
    const tabla = eq(M, "Entrepiso") ? VUELTAS_CINTA_NO_AISLADA.entrepiso_concreto
      : eq(N, "Panel de Yeso") ? VUELTAS_CINTA_NO_AISLADA.pared_gypsum
      : VUELTAS_CINTA_NO_AISLADA.pared_concreto;
    return buscarVueltasEnTabla(tabla, n(row.D));
  }
  return null;
}
